package com.example.barmanagement.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Objects;

@Embeddable
public class BeverageType {

    /*
     * This ID comes from the shared inter-service contract.
     * It is not generated by Bar Management.
     */
    @Column(
            name = "beverage_type_id",
            nullable = false
    )
    private Long id;

    @Column(
            name = "beverage_name",
            nullable = false,
            length = 100
    )
    private String name;

    @Column(
            name = "beverage_price",
            nullable = false,
            precision = 10,
            scale = 2
    )
    private BigDecimal price;

    protected BeverageType() {
        // Required by JPA
    }

    private BeverageType(
            Long id,
            String name,
            BigDecimal price
    ) {
        if (id == null || id <= 0) {
            throw new IllegalArgumentException(
                    "Beverage type ID must be a positive Long value."
            );
        }

        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException(
                    "Beverage name is required."
            );
        }

        this.id = id;
        this.name = name.trim();
        this.price = normalizePrice(price);
    }

    public static BeverageType of(
            Long id,
            String name,
            BigDecimal price
    ) {
        return new BeverageType(id, name, price);
    }

    public BeverageType withNameAndPrice(
            String newName,
            BigDecimal newPrice
    ) {
        return new BeverageType(
                id,
                newName,
                newPrice
        );
    }

    private static BigDecimal normalizePrice(
            BigDecimal price
    ) {
        if (price == null) {
            throw new IllegalArgumentException(
                    "Beverage price is required."
            );
        }

        if (price.signum() < 0) {
            throw new IllegalArgumentException(
                    "Beverage price cannot be negative."
            );
        }

        return price.setScale(
                2,
                RoundingMode.HALF_UP
        );
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public BigDecimal getPrice() {
        return price;
    }

    /*
     * Two local beverage references represent the same
     * beverage type when their shared IDs are equal.
     */
    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }

        if (!(other instanceof BeverageType that)) {
            return false;
        }

        return Objects.equals(id, that.id);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }
}